pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint[] memory v) public {
        // restrict arrays to same length and non-empty
        vm.assume(_tos.length > 0);
        vm.assume(v.length == _tos.length);
        // msg.sender must be the allowed address
        address sender = 0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9;
        vm.prank(sender);
        bool ret;
        bool ok;
        try c.transfer(_tos, v) returns (bool _ret) {
            ret = _ret;
            ok = true;
        } catch {
            ok = false;
        }
        // the property: if the call completes without revert, then the returned value must be true
        assertTrue(!ok || ret);
    }
}

