// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address[] memory _tos, uint256[] memory v) public {
        vm.assume(_tos.length == v.length);
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length <= 10);
        for (uint i = 0; i < v.length; i++) {
            v[i] = bound(v[i], 0, type(uint256).max / 1e18);
        }
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        (bool success, bytes memory returndata) = address(c).call(abi.encodeWithSelector(C.transfer.selector, _tos, v));
        bool ok;
        if (success) {
            ok = abi.decode(returndata, (bool));
        } else {
            // Revert is acceptable; property only required when no revert
            ok = true;
        }
        assertTrue(ok);
    }
}

